import{saveUsersToStorage}from"../services/userService.js";export function renderProfiles(e,l){if(!l)return;l.innerHTML=e.map(e=>{const l=e.isFollowing?"images/person-added.svg":"images/person_add.svg";return`\n      <div class="lk-profile-item" data-id="${e.userId}">\n        <div class="lk-profile-info">\n          <img src="${e.avatar}" class="lk-avatar" alt="${e.name}">\n          <div>\n            <span class="lk-profile-name">${e.name}</span>\n            <p class="lk-follower-count" style="font-size:12px; color:#777; margin:0;">\n              ${e.followerCount} takipçi\n            </p>\n          </div>\n        </div>\n        <div class="lk-profile-actions">\n          <a href="profile-detail.html?userId=${e.userId}" class="lk-btn-incele">İncele</a>\n          \n          <button type="button" class="lk-btn-follow" aria-label="Takip Butonu">\n            <img src="${l}" alt="icon" class="lk-follow-icon">\n          </button>\n        </div>\n      </div>\n    `}).join("");l.querySelectorAll(".lk-btn-follow").forEach(l=>{l.addEventListener("click",o=>{o.preventDefault();const n=l.closest(".lk-profile-item"),s=n.dataset.id,i=e.find(e=>e.userId===s);if(i){i.isFollowing=!i.isFollowing,i.followerCount+=i.isFollowing?1:-1;const o=l.querySelector("img"),s=n.querySelector(".lk-follower-count");o.src=i.isFollowing?"images/person-added.svg":"images/person_add.svg",s.textContent=`${i.followerCount} takipçi`,saveUsersToStorage(e)}})})}